package auth

import (
	"path/filepath"
	"testing"
	"time"

	"amneziawg-web-ui/internal/adminpw"
)

// fileStore is a store backed by a hash file in a temp directory, which is how
// a running panel is configured when WEB_UI_PASSWORD is not set: the password
// is generated by the store itself. The path is returned so a test can rewrite
// the file the way "reset-password" does.
func fileStore(t *testing.T) (*adminpw.Store, string, string) {
	t.Helper()

	path := filepath.Join(t.TempDir(), adminpw.FileName)
	store, password, err := adminpw.Open(path, "")
	if err != nil {
		t.Fatalf("adminpw.Open: %v", err)
	}
	if password == "" {
		t.Fatal("the store did not generate a password")
	}

	return store, password, path
}

func TestCredentialCacheRemembersAVerifiedPair(t *testing.T) {
	c := newCredentialCache(5 * time.Minute)
	now := time.Unix(testNow, 0)
	key := c.key(testUser, testPassword)

	if c.get(key, 0, now) {
		t.Fatal("an entry was found before anything was put")
	}
	c.put(key, 0, now)
	if !c.get(key, 0, now) {
		t.Fatal("a credential that was just verified was not cached")
	}
	if !c.get(key, 0, now.Add(5*time.Minute-time.Second)) {
		t.Error("the entry expired before its five minutes were up")
	}
	if c.get(key, 0, now.Add(5*time.Minute)) {
		t.Error("the entry is still there at its expiry")
	}
	if c.get(c.key(testUser, "another password"), 0, now) {
		t.Error("one credential answered for another")
	}
}

// The key is an HMAC under a per-process secret, so two pairs do not collide
// and nothing that can be turned back into a password is stored.
func TestCredentialCacheKeysSeparateTheFields(t *testing.T) {
	c := newCredentialCache(time.Minute)

	if c.key("ab", "c") == c.key("a", "bc") {
		t.Error("the user and the password are concatenated without a separator")
	}
	if c.key(testUser, testPassword) == c.key(testUser, testPassword+" ") {
		t.Error("two different passwords produced the same key")
	}
	if c.key(testUser, testPassword) == newCredentialCache(time.Minute).key(testUser, testPassword) {
		t.Error("two processes share a cache key: the secret is not per process")
	}
}

// A password change is a new generation, and an entry written under the old
// one is not an answer any more.
func TestCredentialCacheDropsTheOldGeneration(t *testing.T) {
	c := newCredentialCache(time.Minute)
	now := time.Unix(testNow, 0)
	key := c.key(testUser, testPassword)

	c.put(key, 3, now)
	if !c.get(key, 3, now) {
		t.Fatal("the entry was not stored")
	}
	if c.get(key, 4, now) {
		t.Fatal("an entry survived the password change it was written before")
	}
	if c.get(key, 3, now) {
		t.Error("the stale entry was kept instead of dropped")
	}
}

// Without random bytes the cache stays off: a keyed cache whose key can be
// guessed is worse than verifying every request.
func TestCredentialCacheIsOffWithoutARandomKey(t *testing.T) {
	c := newCredentialCache(time.Minute)
	c.enabled = false
	now := time.Unix(testNow, 0)
	key := c.key(testUser, testPassword)

	c.put(key, 0, now)
	if c.get(key, 0, now) {
		t.Fatal("a disabled cache answered a lookup")
	}
}

// A verified Basic credential is served from the cache, and a wrong one is
// not: the cache only ever holds pairs that worked.
func TestCheckCachesOnlySuccessfulCredentials(t *testing.T) {
	a := newTestAuth()

	if !a.Check(testUser, testPassword) {
		t.Fatal("the right password was refused")
	}
	if !a.verified.get(a.verified.key(testUser, testPassword), 0, a.now()) {
		t.Error("a verified credential was not cached")
	}
	if a.Check(testUser, "wrong") {
		t.Fatal("a wrong password was accepted")
	}
	if a.verified.get(a.verified.key(testUser, "wrong"), 0, a.now()) {
		t.Error("a wrong password was cached")
	}
}

// No more than verifyConcurrency hashes run at a time: the semaphore is what
// keeps a script's polling from turning into a memory spike.
func TestCheckIsBoundedByTheSemaphore(t *testing.T) {
	a := newTestAuth()

	// Take every slot the semaphore has: a check started now has to wait.
	for range verifyConcurrency {
		a.sem <- struct{}{}
	}
	done := make(chan bool, 1)
	go func() { done <- a.Check(testUser, testPassword) }()

	select {
	case <-done:
		t.Fatal("a verification ran while every slot was taken")
	case <-time.After(50 * time.Millisecond):
	}

	<-a.sem
	select {
	case ok := <-done:
		if !ok {
			t.Error("the verification failed once a slot was free")
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the verification did not run after a slot was released")
	}
}

// Rewriting the hash file is how "reset-password" reaches a running panel: the
// old password, the cached credential and every issued session stop working,
// and the new password works, without a restart.
func TestRewrittenPasswordIsAdoptedWithoutARestart(t *testing.T) {
	store, oldPassword, path := fileStore(t)
	a := New(testUser, store)
	now := time.Unix(testNow, 0)
	token := a.issue(now)

	if !a.Check(testUser, oldPassword) {
		t.Fatal("the generated password was refused")
	}
	if !a.sessionValid(token, now) {
		t.Fatal("a session issued under the first password is not valid")
	}

	newPassword, err := adminpw.Reset(path)
	if err != nil {
		t.Fatalf("adminpw.Reset: %v", err)
	}
	// The store looks at the file at most once a second.
	time.Sleep(time.Second + 100*time.Millisecond)

	if a.Check(testUser, oldPassword) {
		t.Error("the old password still works after it was reset")
	}
	if !a.Check(testUser, newPassword) {
		t.Error("the new password does not work")
	}
	if a.sessionValid(token, now) {
		t.Error("a session issued under the old password is still valid")
	}
}
